sealed class NimbusException(message: String): kotlin.Exception(message) {
        
        class InvalidPersistedData(message: String) : NimbusException(message)
        
        class RkvException(message: String) : NimbusException(message)
        
        class IoException(message: String) : NimbusException(message)
        
        class JsonException(message: String) : NimbusException(message)
        
        class EvaluationException(message: String) : NimbusException(message)
        
        class InvalidExpression(message: String) : NimbusException(message)
        
        class InvalidFraction(message: String) : NimbusException(message)
        
        class TryFromSliceException(message: String) : NimbusException(message)
        
        class EmptyRatiosException(message: String) : NimbusException(message)
        
        class OutOfBoundsException(message: String) : NimbusException(message)
        
        class UrlParsingException(message: String) : NimbusException(message)
        
        class UuidException(message: String) : NimbusException(message)
        
        class InvalidExperimentFormat(message: String) : NimbusException(message)
        
        class InvalidPath(message: String) : NimbusException(message)
        
        class InternalException(message: String) : NimbusException(message)
        
        class NoSuchExperiment(message: String) : NimbusException(message)
        
        class NoSuchBranch(message: String) : NimbusException(message)
        
        class DatabaseNotReady(message: String) : NimbusException(message)
        
        class VersionParsingException(message: String) : NimbusException(message)
        
        class BehaviorException(message: String) : NimbusException(message)
        
        class TryFromIntException(message: String) : NimbusException(message)
        
        class ParseIntException(message: String) : NimbusException(message)
        
        class TransformParameterException(message: String) : NimbusException(message)
        
        class ClientException(message: String) : NimbusException(message)
        
        class UniFfiCallbackException(message: String) : NimbusException(message)
        
        class RegexException(message: String) : NimbusException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<NimbusException> {
        override fun lift(error_buf: RustBuffer.ByValue): NimbusException = FfiConverterTypeNimbusError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeNimbusError : FfiConverterRustBuffer<NimbusException> {
    override fun read(buf: ByteBuffer): NimbusException {
        
            return when(buf.getInt()) {
            1 -> NimbusException.InvalidPersistedData(FfiConverterString.read(buf))
            2 -> NimbusException.RkvException(FfiConverterString.read(buf))
            3 -> NimbusException.IoException(FfiConverterString.read(buf))
            4 -> NimbusException.JsonException(FfiConverterString.read(buf))
            5 -> NimbusException.EvaluationException(FfiConverterString.read(buf))
            6 -> NimbusException.InvalidExpression(FfiConverterString.read(buf))
            7 -> NimbusException.InvalidFraction(FfiConverterString.read(buf))
            8 -> NimbusException.TryFromSliceException(FfiConverterString.read(buf))
            9 -> NimbusException.EmptyRatiosException(FfiConverterString.read(buf))
            10 -> NimbusException.OutOfBoundsException(FfiConverterString.read(buf))
            11 -> NimbusException.UrlParsingException(FfiConverterString.read(buf))
            12 -> NimbusException.UuidException(FfiConverterString.read(buf))
            13 -> NimbusException.InvalidExperimentFormat(FfiConverterString.read(buf))
            14 -> NimbusException.InvalidPath(FfiConverterString.read(buf))
            15 -> NimbusException.InternalException(FfiConverterString.read(buf))
            16 -> NimbusException.NoSuchExperiment(FfiConverterString.read(buf))
            17 -> NimbusException.NoSuchBranch(FfiConverterString.read(buf))
            18 -> NimbusException.DatabaseNotReady(FfiConverterString.read(buf))
            19 -> NimbusException.VersionParsingException(FfiConverterString.read(buf))
            20 -> NimbusException.BehaviorException(FfiConverterString.read(buf))
            21 -> NimbusException.TryFromIntException(FfiConverterString.read(buf))
            22 -> NimbusException.ParseIntException(FfiConverterString.read(buf))
            23 -> NimbusException.TransformParameterException(FfiConverterString.read(buf))
            24 -> NimbusException.ClientException(FfiConverterString.read(buf))
            25 -> NimbusException.UniFfiCallbackException(FfiConverterString.read(buf))
            26 -> NimbusException.RegexException(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: NimbusException): ULong {
        return 4UL
    }

    override fun write(value: NimbusException, buf: ByteBuffer) {
        when(value) {
            is NimbusException.InvalidPersistedData -> {
                buf.putInt(1)
                Unit
            }
            is NimbusException.RkvException -> {
                buf.putInt(2)
                Unit
            }
            is NimbusException.IoException -> {
                buf.putInt(3)
                Unit
            }
            is NimbusException.JsonException -> {
                buf.putInt(4)
                Unit
            }
            is NimbusException.EvaluationException -> {
                buf.putInt(5)
                Unit
            }
            is NimbusException.InvalidExpression -> {
                buf.putInt(6)
                Unit
            }
            is NimbusException.InvalidFraction -> {
                buf.putInt(7)
                Unit
            }
            is NimbusException.TryFromSliceException -> {
                buf.putInt(8)
                Unit
            }
            is NimbusException.EmptyRatiosException -> {
                buf.putInt(9)
                Unit
            }
            is NimbusException.OutOfBoundsException -> {
                buf.putInt(10)
                Unit
            }
            is NimbusException.UrlParsingException -> {
                buf.putInt(11)
                Unit
            }
            is NimbusException.UuidException -> {
                buf.putInt(12)
                Unit
            }
            is NimbusException.InvalidExperimentFormat -> {
                buf.putInt(13)
                Unit
            }
            is NimbusException.InvalidPath -> {
                buf.putInt(14)
                Unit
            }
            is NimbusException.InternalException -> {
                buf.putInt(15)
                Unit
            }
            is NimbusException.NoSuchExperiment -> {
                buf.putInt(16)
                Unit
            }
            is NimbusException.NoSuchBranch -> {
                buf.putInt(17)
                Unit
            }
            is NimbusException.DatabaseNotReady -> {
                buf.putInt(18)
                Unit
            }
            is NimbusException.VersionParsingException -> {
                buf.putInt(19)
                Unit
            }
            is NimbusException.BehaviorException -> {
                buf.putInt(20)
                Unit
            }
            is NimbusException.TryFromIntException -> {
                buf.putInt(21)
                Unit
            }
            is NimbusException.ParseIntException -> {
                buf.putInt(22)
                Unit
            }
            is NimbusException.TransformParameterException -> {
                buf.putInt(23)
                Unit
            }
            is NimbusException.ClientException -> {
                buf.putInt(24)
                Unit
            }
            is NimbusException.UniFfiCallbackException -> {
                buf.putInt(25)
                Unit
            }
            is NimbusException.RegexException -> {
                buf.putInt(26)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




