/**
 * Typealias from the type name used in the UDL file to the custom type.  This
 * is needed because the UDL type name is used in function/method signatures.
 * It's also what we have an external type that references a custom type.
 */
public typealias JsonObject = JSONObject


/**
 * @suppress
 */
public object FfiConverterTypeJsonObject: FfiConverter<JsonObject, RustBuffer.ByValue> {
    override fun lift(value: RustBuffer.ByValue): JsonObject {
        val builtinValue = FfiConverterString.lift(value)
        return JSONObject(builtinValue)
    }

    override fun lower(value: JsonObject): RustBuffer.ByValue {
        val builtinValue = value.toString()
        return FfiConverterString.lower(builtinValue)
    }

    override fun read(buf: ByteBuffer): JsonObject {
        val builtinValue = FfiConverterString.read(buf)
        return JSONObject(builtinValue)
    }

    override fun allocationSize(value: JsonObject): ULong {
        val builtinValue = value.toString()
        return FfiConverterString.allocationSize(builtinValue)
    }

    override fun write(value: JsonObject, buf: ByteBuffer) {
        val builtinValue = value.toString()
        FfiConverterString.write(builtinValue, buf)
    }
}



